insert into pg_temp.school967_civic_edition(payload) values ($school_civic_edition$[{"slug":"how-state-works","index":0,"old_lessons":[{"title":"الفكرة الأساسية","body":"الدولة تنظيم سياسي له سكان وإقليم ومؤسسات تمارس السلطة؛ أما السيادة فتصف استقلال القرار العام ضمن قواعد القانون الدولي. لفهم هذا الدرس حدّد ما الذي يصفه المصطلح، والجهة أو العلاقة التي يتناولها، ثم فرّق بين الوصف النظري والممارسة الفعلية.","example":"سيادة","note":"استوعب العلاقة الأساسية قبل الاستنتاج منها."},{"title":"حالة تطبيقية محلولة","body":"حين تتفاوض دولتان على اتفاقية تمارس كل منهما صلاحياتها الخارجية عبر مؤسساتها المخولة. جرّب تحليل الموقف بهذا الترتيب: حدد الإقليم ← حدد المؤسسات ← ميز بين الاختصاص الداخلي والخارجي. لا تنتقل إلى التقييم قبل توضيح المعطيات والجهات المعنية.","example":"حدد الإقليم ← حدد المؤسسات ← ميز بين الاختصاص الداخلي والخارجي","note":"هذه حالة افتراضية للتعلم وليست وصفًا لبلد أو مؤسسة بعينها."},{"title":"القيود والأخطاء الشائعة","body":"لا تعني السيادة أن جميع قرارات الحكومة مباحة أو أنها خارج الالتزامات القانونية الدولية. عندما تصل إلى نتيجة، اذكر افتراضاتك وتأكد أن المعلومات كافية؛ فالموضوع قد يختلف باختلاف القواعد والظروف والبيانات.","example":"تحقق من الحدود قبل تعميم النتيجة","note":"التقييم يعتمد على استدلالك وفهمك وليس على رأيك السياسي."}],"old_intro":"الدولة تنظيم سياسي له سكان وإقليم ومؤسسات تمارس السلطة؛ أما السيادة فتصف استقلال القرار العام ضمن قواعد القانون الدولي. حين تتفاوض دولتان على اتفاقية تمارس كل منهما صلاحياتها الخارجية عبر مؤسساتها المخولة.","lessons":[{"title":"فهم المفهوم من البداية","body":"الدولة تنظيم سياسي له سكان وإقليم ومؤسسات تمارس السلطة؛ أما السيادة فتصف استقلال القرار العام ضمن قواعد القانون الدولي.\n\nقد توجد وزارة أو مجلس بلدي داخل دولة، لكن المؤسسة وحدها ليست دولة. اسأل دائمًا: من يضع القواعد العامة، وعلى أي إقليم تسري، ومن يمثل الدولة خارجيًا؟","example":"سيادة","note":"لا تحفظ المصطلح وحده: حاول أن تشرح فكرته بلغة بسيطة وبمثال قريب منك."},{"title":"مثال محلول: ماذا حدث؟","body":"حين تتفاوض دولتان على اتفاقية تمارس كل منهما صلاحياتها الخارجية عبر مؤسساتها المخولة.\n\nوالآن تخيّل الموقف التالي: مدينة صغيرة فيها سكان وأرض وسلطة بلدية، لكنها جزء من دولة قائمة.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.","example":"مدينة صغيرة فيها سكان وأرض وسلطة بلدية، لكنها جزء من دولة قائمة.","note":"اقرأ السيناريو، وحدد المعطيات التي تعرفها قبل أي استنتاج."},{"title":"خطوات حل موقف مشابه","body":"أمامك موقف عملي في «الدولة والسيادة». مدينة صغيرة فيها سكان وأرض وسلطة بلدية، لكنها جزء من دولة قائمة.\n\nالبلدية تدير شؤونًا محلية، أما الدولة فتضم إقليمًا وسكانًا وسلطة وسيادة. لا تكفي المباني أو الأسواق وحدها.\n\nحتى تصل إلى تفسير سليم، مرّ على الإجراءات التالية بالترتيب. اشرح لنفسك لماذا تحتاج كل خطوة قبل الانتقال للأخرى.","example":"حدد الإقليم ← حدد المؤسسات ← ميز بين الاختصاص الداخلي والخارجي","note":"لا تتخطى خطوة لم تفهمها. قارن الإجابة بوقائع السيناريو."},{"title":"الحدود والأخطاء الشائعة","body":"لا تعني السيادة أن جميع قرارات الحكومة مباحة أو أنها خارج الالتزامات القانونية الدولية.\n\nسؤال للمراجعة: ما الذي ينقصها لتوصف دولة مستقلة؟\n\nإذا لم تتوافر معلومات كافية للإجابة، فهذه علامة أنك تحتاج إلى بيانات أو قانون أو فترة مقارنة أو افتراضات أوضح. فهم ما لا تعرفه جزء أساسي من التحليل.","example":"ما الذي ينقصها لتوصف دولة مستقلة؟","note":"راجع خطأ شائعًا في هذا الموضوع ثم عد إلى المثال لتتأكد من فهمك."}],"intro":"في هذه المحطة سنفهم «الدولة والسيادة» من البداية، من دون افتراض معرفة سابقة.\n\nالدولة تنظيم سياسي له سكان وإقليم ومؤسسات تمارس السلطة؛ أما السيادة فتصف استقلال القرار العام ضمن قواعد القانون الدولي.\n\nثم سنرى كيف تظهر الفكرة عمليًا، وما الذي قد نسيء فهمه: حين تتفاوض دولتان على اتفاقية تمارس كل منهما صلاحياتها الخارجية عبر مؤسساتها المخولة."},{"slug":"how-state-works","index":1,"old_lessons":[{"title":"الفكرة الأساسية","body":"المواطنة رابطة قانونية وسياسية بين الفرد والدولة ترتبط بحقوق وواجبات، وتختلف عن مجرد الإقامة في الإقليم. لفهم هذا الدرس حدّد ما الذي يصفه المصطلح، والجهة أو العلاقة التي يتناولها، ثم فرّق بين الوصف النظري والممارسة الفعلية.","example":"مواطنة","note":"استوعب العلاقة الأساسية قبل الاستنتاج منها."},{"title":"حالة تطبيقية محلولة","body":"قد يقيم شخص لسنوات في بلد دون أن يحمل جنسيته؛ إقامته لا تعطيه تلقائيًا جميع حقوق الجنسية. جرّب تحليل الموقف بهذا الترتيب: حدد صفة الشخص ← راجع حقوقه القانونية ← ميز بين الجنسية والإقامة. لا تنتقل إلى التقييم قبل توضيح المعطيات والجهات المعنية.","example":"حدد صفة الشخص ← راجع حقوقه القانونية ← ميز بين الجنسية والإقامة","note":"هذه حالة افتراضية للتعلم وليست وصفًا لبلد أو مؤسسة بعينها."},{"title":"القيود والأخطاء الشائعة","body":"لا تخلط بين الهوية الثقافية والجنسية القانونية؛ تختلف شروط اكتساب الجنسية بين الدول. عندما تصل إلى نتيجة، اذكر افتراضاتك وتأكد أن المعلومات كافية؛ فالموضوع قد يختلف باختلاف القواعد والظروف والبيانات.","example":"تحقق من الحدود قبل تعميم النتيجة","note":"التقييم يعتمد على استدلالك وفهمك وليس على رأيك السياسي."}],"old_intro":"المواطنة رابطة قانونية وسياسية بين الفرد والدولة ترتبط بحقوق وواجبات، وتختلف عن مجرد الإقامة في الإقليم. قد يقيم شخص لسنوات في بلد دون أن يحمل جنسيته؛ إقامته لا تعطيه تلقائيًا جميع حقوق الجنسية.","lessons":[{"title":"فهم المفهوم من البداية","body":"المواطنة رابطة قانونية وسياسية بين الفرد والدولة ترتبط بحقوق وواجبات، وتختلف عن مجرد الإقامة في الإقليم.\n\nيمكن لشخص أن يشارك في المجتمع ويعمل ويدفع ضرائب من دون أن يحمل الجنسية. افصل بين حياة الفرد اليومية وصفته القانونية وحقوقه الانتخابية.","example":"مواطنة","note":"لا تحفظ المصطلح وحده: حاول أن تشرح فكرته بلغة بسيطة وبمثال قريب منك."},{"title":"مثال محلول: ماذا حدث؟","body":"قد يقيم شخص لسنوات في بلد دون أن يحمل جنسيته؛ إقامته لا تعطيه تلقائيًا جميع حقوق الجنسية.\n\nوالآن تخيّل الموقف التالي: تقيم سلمى في بلد منذ خمس سنوات بإقامة قانونية لكنها لا تحمل جنسيته.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.","example":"تقيم سلمى في بلد منذ خمس سنوات بإقامة قانونية لكنها لا تحمل جنسيته.","note":"اقرأ السيناريو، وحدد المعطيات التي تعرفها قبل أي استنتاج."},{"title":"خطوات حل موقف مشابه","body":"أمامك موقف عملي في «الشعب والمواطنة». تقيم سلمى في بلد منذ خمس سنوات بإقامة قانونية لكنها لا تحمل جنسيته.\n\nحقوق التصويت ترتبط بالقانون والصفة الانتخابية ولا تُستنتج تلقائيًا من طول الإقامة.\n\nحتى تصل إلى تفسير سليم، مرّ على الإجراءات التالية بالترتيب. اشرح لنفسك لماذا تحتاج كل خطوة قبل الانتقال للأخرى.","example":"حدد صفة الشخص ← راجع حقوقه القانونية ← ميز بين الجنسية والإقامة","note":"لا تتخطى خطوة لم تفهمها. قارن الإجابة بوقائع السيناريو."},{"title":"الحدود والأخطاء الشائعة","body":"لا تخلط بين الهوية الثقافية والجنسية القانونية؛ تختلف شروط اكتساب الجنسية بين الدول.\n\nسؤال للمراجعة: ما المعلومة التي تحتاجها لتعرف هل تملك حق التصويت الوطني؟\n\nإذا لم تتوافر معلومات كافية للإجابة، فهذه علامة أنك تحتاج إلى بيانات أو قانون أو فترة مقارنة أو افتراضات أوضح. فهم ما لا تعرفه جزء أساسي من التحليل.","example":"ما المعلومة التي تحتاجها لتعرف هل تملك حق التصويت الوطني؟","note":"راجع خطأ شائعًا في هذا الموضوع ثم عد إلى المثال لتتأكد من فهمك."}],"intro":"في هذه المحطة سنفهم «الشعب والمواطنة» من البداية، من دون افتراض معرفة سابقة.\n\nالمواطنة رابطة قانونية وسياسية بين الفرد والدولة ترتبط بحقوق وواجبات، وتختلف عن مجرد الإقامة في الإقليم.\n\nثم سنرى كيف تظهر الفكرة عمليًا، وما الذي قد نسيء فهمه: قد يقيم شخص لسنوات في بلد دون أن يحمل جنسيته؛ إقامته لا تعطيه تلقائيًا جميع حقوق الجنسية."},{"slug":"how-state-works","index":2,"old_lessons":[{"title":"الفكرة الأساسية","body":"الدستور ينظم شكل الدولة والسلطات وحقوق الأفراد وآليات تعديل القواعد الأساسية وفق نظامها القانوني. لفهم هذا الدرس حدّد ما الذي يصفه المصطلح، والجهة أو العلاقة التي يتناولها، ثم فرّق بين الوصف النظري والممارسة الفعلية.","example":"دستور","note":"استوعب العلاقة الأساسية قبل الاستنتاج منها."},{"title":"حالة تطبيقية محلولة","body":"إذا وقع خلاف حول صلاحية مؤسسة فقد تُراجع النصوص الدستورية لتحديد صاحب الاختصاص. جرّب تحليل الموقف بهذا الترتيب: حدد النص الدستوري ← قارن الاختصاصات ← افحص آلية الرقابة. لا تنتقل إلى التقييم قبل توضيح المعطيات والجهات المعنية.","example":"حدد النص الدستوري ← قارن الاختصاصات ← افحص آلية الرقابة","note":"هذه حالة افتراضية للتعلم وليست وصفًا لبلد أو مؤسسة بعينها."},{"title":"القيود والأخطاء الشائعة","body":"وجود دستور مكتوب وحده لا يثبت تطبيق أحكامه؛ يجب فحص الممارسة والمؤسسات والرقابة. عندما تصل إلى نتيجة، اذكر افتراضاتك وتأكد أن المعلومات كافية؛ فالموضوع قد يختلف باختلاف القواعد والظروف والبيانات.","example":"تحقق من الحدود قبل تعميم النتيجة","note":"التقييم يعتمد على استدلالك وفهمك وليس على رأيك السياسي."}],"old_intro":"الدستور ينظم شكل الدولة والسلطات وحقوق الأفراد وآليات تعديل القواعد الأساسية وفق نظامها القانوني. إذا وقع خلاف حول صلاحية مؤسسة فقد تُراجع النصوص الدستورية لتحديد صاحب الاختصاص.","lessons":[{"title":"فهم المفهوم من البداية","body":"الدستور ينظم شكل الدولة والسلطات وحقوق الأفراد وآليات تعديل القواعد الأساسية وفق نظامها القانوني.\n\nفكر في الدستور كخريطة للصلاحيات لا كملصق شعارات. عند النزاع لا تكفي رغبات المسؤولين؛ يجب الرجوع إلى القواعد التي تحدد من يقرر وكيف.","example":"دستور","note":"لا تحفظ المصطلح وحده: حاول أن تشرح فكرته بلغة بسيطة وبمثال قريب منك."},{"title":"مثال محلول: ماذا حدث؟","body":"إذا وقع خلاف حول صلاحية مؤسسة فقد تُراجع النصوص الدستورية لتحديد صاحب الاختصاص.\n\nوالآن تخيّل الموقف التالي: وزارة ومجلس محلي يختلفان حول من يملك إصدار قرار. كيف تبحث عن الإجابة؟\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.","example":"وزارة ومجلس محلي يختلفان حول من يملك إصدار قرار. كيف تبحث عن الإجابة؟","note":"اقرأ السيناريو، وحدد المعطيات التي تعرفها قبل أي استنتاج."},{"title":"خطوات حل موقف مشابه","body":"أمامك موقف عملي في «الدستور والقواعد العليا». وزارة ومجلس محلي يختلفان حول من يملك إصدار قرار. كيف تبحث عن الإجابة؟\n\nلا تبدأ بترجيح جهة لأن اسمها أكبر؛ اقرأ سند الاختصاص أولًا.\n\nحتى تصل إلى تفسير سليم، مرّ على الإجراءات التالية بالترتيب. اشرح لنفسك لماذا تحتاج كل خطوة قبل الانتقال للأخرى.","example":"حدد النص الدستوري ← قارن الاختصاصات ← افحص آلية الرقابة","note":"لا تتخطى خطوة لم تفهمها. قارن الإجابة بوقائع السيناريو."},{"title":"الحدود والأخطاء الشائعة","body":"وجود دستور مكتوب وحده لا يثبت تطبيق أحكامه؛ يجب فحص الممارسة والمؤسسات والرقابة.\n\nسؤال للمراجعة: ما أول إجراء واضح يمكن فعله وفق ما تعلمته؟\n\nإذا لم تتوافر معلومات كافية للإجابة، فهذه علامة أنك تحتاج إلى بيانات أو قانون أو فترة مقارنة أو افتراضات أوضح. فهم ما لا تعرفه جزء أساسي من التحليل.","example":"ما أول إجراء واضح يمكن فعله وفق ما تعلمته؟","note":"راجع خطأ شائعًا في هذا الموضوع ثم عد إلى المثال لتتأكد من فهمك."}],"intro":"في هذه المحطة سنفهم «الدستور والقواعد العليا» من البداية، من دون افتراض معرفة سابقة.\n\nالدستور ينظم شكل الدولة والسلطات وحقوق الأفراد وآليات تعديل القواعد الأساسية وفق نظامها القانوني.\n\nثم سنرى كيف تظهر الفكرة عمليًا، وما الذي قد نسيء فهمه: إذا وقع خلاف حول صلاحية مؤسسة فقد تُراجع النصوص الدستورية لتحديد صاحب الاختصاص."},{"slug":"how-state-works","index":3,"old_lessons":[{"title":"الفكرة الأساسية","body":"الفصل بين السلطات يوزع التشريع والتنفيذ والقضاء بين مؤسسات تختلف صلاحياتها وطرق الرقابة المتبادلة. لفهم هذا الدرس حدّد ما الذي يصفه المصطلح، والجهة أو العلاقة التي يتناولها، ثم فرّق بين الوصف النظري والممارسة الفعلية.","example":"الفصل بين السلطات","note":"استوعب العلاقة الأساسية قبل الاستنتاج منها."},{"title":"حالة تطبيقية محلولة","body":"حين تُقر مؤسسة تشريعية قانونًا وتطبقه الإدارة ويفصل القضاء في النزاع تظهر وظائف مختلفة. جرّب تحليل الموقف بهذا الترتيب: حدد الوظيفة ← عين المؤسسة ← افحص حدود الرقابة. لا تنتقل إلى التقييم قبل توضيح المعطيات والجهات المعنية.","example":"حدد الوظيفة ← عين المؤسسة ← افحص حدود الرقابة","note":"هذه حالة افتراضية للتعلم وليست وصفًا لبلد أو مؤسسة بعينها."},{"title":"القيود والأخطاء الشائعة","body":"الفصل لا يعني انقطاع التواصل الكامل بين السلطات؛ درجات الفصل والتعاون تتفاوت بين الأنظمة. عندما تصل إلى نتيجة، اذكر افتراضاتك وتأكد أن المعلومات كافية؛ فالموضوع قد يختلف باختلاف القواعد والظروف والبيانات.","example":"تحقق من الحدود قبل تعميم النتيجة","note":"التقييم يعتمد على استدلالك وفهمك وليس على رأيك السياسي."}],"old_intro":"الفصل بين السلطات يوزع التشريع والتنفيذ والقضاء بين مؤسسات تختلف صلاحياتها وطرق الرقابة المتبادلة. حين تُقر مؤسسة تشريعية قانونًا وتطبقه الإدارة ويفصل القضاء في النزاع تظهر وظائف مختلفة.","lessons":[{"title":"فهم المفهوم من البداية","body":"الفصل بين السلطات يوزع التشريع والتنفيذ والقضاء بين مؤسسات تختلف صلاحياتها وطرق الرقابة المتبادلة.\n\nتخيل ثلاث وظائف: كتابة القاعدة، تنفيذها، ثم الفصل في الخلاف حولها. توزيع الوظائف يساعد على تحديد المسؤولية وطرق المراجعة، ولا يمنع تعاون المؤسسات.","example":"الفصل بين السلطات","note":"لا تحفظ المصطلح وحده: حاول أن تشرح فكرته بلغة بسيطة وبمثال قريب منك."},{"title":"مثال محلول: ماذا حدث؟","body":"حين تُقر مؤسسة تشريعية قانونًا وتطبقه الإدارة ويفصل القضاء في النزاع تظهر وظائف مختلفة.\n\nوالآن تخيّل الموقف التالي: مشروع قانون عن المدارس: مؤسسة تقترح، أخرى تقر، وثالثة تنظر في نزاع محتمل.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.","example":"مشروع قانون عن المدارس: مؤسسة تقترح، أخرى تقر، وثالثة تنظر في نزاع محتمل.","note":"اقرأ السيناريو، وحدد المعطيات التي تعرفها قبل أي استنتاج."},{"title":"خطوات حل موقف مشابه","body":"أمامك موقف عملي في «الفصل بين السلطات». مشروع قانون عن المدارس: مؤسسة تقترح، أخرى تقر، وثالثة تنظر في نزاع محتمل.\n\nتوزيع الوظائف يمنع خلط إصدار القاعدة بتنفيذها والفصل في النزاع، مع اختلاف التفاصيل بين الدساتير.\n\nحتى تصل إلى تفسير سليم، مرّ على الإجراءات التالية بالترتيب. اشرح لنفسك لماذا تحتاج كل خطوة قبل الانتقال للأخرى.","example":"حدد الوظيفة ← عين المؤسسة ← افحص حدود الرقابة","note":"لا تتخطى خطوة لم تفهمها. قارن الإجابة بوقائع السيناريو."},{"title":"الحدود والأخطاء الشائعة","body":"الفصل لا يعني انقطاع التواصل الكامل بين السلطات؛ درجات الفصل والتعاون تتفاوت بين الأنظمة.\n\nسؤال للمراجعة: استعرض وظيفة كل جهة في هذا المشروع.\n\nإذا لم تتوافر معلومات كافية للإجابة، فهذه علامة أنك تحتاج إلى بيانات أو قانون أو فترة مقارنة أو افتراضات أوضح. فهم ما لا تعرفه جزء أساسي من التحليل.","example":"استعرض وظيفة كل جهة في هذا المشروع.","note":"راجع خطأ شائعًا في هذا الموضوع ثم عد إلى المثال لتتأكد من فهمك."}],"intro":"في هذه المحطة سنفهم «الفصل بين السلطات» من البداية، من دون افتراض معرفة سابقة.\n\nالفصل بين السلطات يوزع التشريع والتنفيذ والقضاء بين مؤسسات تختلف صلاحياتها وطرق الرقابة المتبادلة.\n\nثم سنرى كيف تظهر الفكرة عمليًا، وما الذي قد نسيء فهمه: حين تُقر مؤسسة تشريعية قانونًا وتطبقه الإدارة ويفصل القضاء في النزاع تظهر وظائف مختلفة."},{"slug":"how-state-works","index":4,"old_lessons":[{"title":"الفكرة الأساسية","body":"السلطة التشريعية تبحث مشاريع القوانين وتعتمدها وفق الإجراءات المعتمدة وقد تراقب عمل الحكومة والمال العام. لفهم هذا الدرس حدّد ما الذي يصفه المصطلح، والجهة أو العلاقة التي يتناولها، ثم فرّق بين الوصف النظري والممارسة الفعلية.","example":"تشريع","note":"استوعب العلاقة الأساسية قبل الاستنتاج منها."},{"title":"حالة تطبيقية محلولة","body":"يناقش البرلمان مقترح ضريبة ويعدله ويصوت عليه بدل أن تطبقه جهة إدارية دون سند قانوني. جرّب تحليل الموقف بهذا الترتيب: اقرأ مشروع القانون ← ناقش التعديلات ← حدد نتيجة التصويت. لا تنتقل إلى التقييم قبل توضيح المعطيات والجهات المعنية.","example":"اقرأ مشروع القانون ← ناقش التعديلات ← حدد نتيجة التصويت","note":"هذه حالة افتراضية للتعلم وليست وصفًا لبلد أو مؤسسة بعينها."},{"title":"القيود والأخطاء الشائعة","body":"لا تعني مناقشة البرلمان لقانون أنه أقره؛ قد يمر بمراحل ولجان وتصويت ومراجعة. عندما تصل إلى نتيجة، اذكر افتراضاتك وتأكد أن المعلومات كافية؛ فالموضوع قد يختلف باختلاف القواعد والظروف والبيانات.","example":"تحقق من الحدود قبل تعميم النتيجة","note":"التقييم يعتمد على استدلالك وفهمك وليس على رأيك السياسي."}],"old_intro":"السلطة التشريعية تبحث مشاريع القوانين وتعتمدها وفق الإجراءات المعتمدة وقد تراقب عمل الحكومة والمال العام. يناقش البرلمان مقترح ضريبة ويعدله ويصوت عليه بدل أن تطبقه جهة إدارية دون سند قانوني.","lessons":[{"title":"فهم المفهوم من البداية","body":"السلطة التشريعية تبحث مشاريع القوانين وتعتمدها وفق الإجراءات المعتمدة وقد تراقب عمل الحكومة والمال العام.\n\nالقانون لا يصبح نافذًا لمجرد أن أحدهم اقترح فكرته. توجد مراحل للنقاش والمراجعة والتصويت والإصدار، تختلف في تفاصيلها حسب النظام.","example":"تشريع","note":"لا تحفظ المصطلح وحده: حاول أن تشرح فكرته بلغة بسيطة وبمثال قريب منك."},{"title":"مثال محلول: ماذا حدث؟","body":"يناقش البرلمان مقترح ضريبة ويعدله ويصوت عليه بدل أن تطبقه جهة إدارية دون سند قانوني.\n\nوالآن تخيّل الموقف التالي: وصل مقترح جديد إلى مجلس تشريعي. رتّب ما يحدث في مثال إجرائي مبسط.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.","example":"وصل مقترح جديد إلى مجلس تشريعي. رتّب ما يحدث في مثال إجرائي مبسط.","note":"اقرأ السيناريو، وحدد المعطيات التي تعرفها قبل أي استنتاج."},{"title":"خطوات حل موقف مشابه","body":"أمامك موقف عملي في «السلطة التشريعية». وصل مقترح جديد إلى مجلس تشريعي. رتّب ما يحدث في مثال إجرائي مبسط.\n\nبعض الأنظمة تتضمن غرفًا متعددة أو مراجعات إضافية، لكن القانون لا يُنفذ بوصفه تشريعًا قبل استكمال إجراءاته.\n\nحتى تصل إلى تفسير سليم، مرّ على الإجراءات التالية بالترتيب. اشرح لنفسك لماذا تحتاج كل خطوة قبل الانتقال للأخرى.","example":"اقرأ مشروع القانون ← ناقش التعديلات ← حدد نتيجة التصويت","note":"لا تتخطى خطوة لم تفهمها. قارن الإجابة بوقائع السيناريو."},{"title":"الحدود والأخطاء الشائعة","body":"لا تعني مناقشة البرلمان لقانون أنه أقره؛ قد يمر بمراحل ولجان وتصويت ومراجعة.\n\nسؤال للمراجعة: ما أول إجراء واضح يمكن فعله وفق ما تعلمته؟\n\nإذا لم تتوافر معلومات كافية للإجابة، فهذه علامة أنك تحتاج إلى بيانات أو قانون أو فترة مقارنة أو افتراضات أوضح. فهم ما لا تعرفه جزء أساسي من التحليل.","example":"ما أول إجراء واضح يمكن فعله وفق ما تعلمته؟","note":"راجع خطأ شائعًا في هذا الموضوع ثم عد إلى المثال لتتأكد من فهمك."}],"intro":"في هذه المحطة سنفهم «السلطة التشريعية» من البداية، من دون افتراض معرفة سابقة.\n\nالسلطة التشريعية تبحث مشاريع القوانين وتعتمدها وفق الإجراءات المعتمدة وقد تراقب عمل الحكومة والمال العام.\n\nثم سنرى كيف تظهر الفكرة عمليًا، وما الذي قد نسيء فهمه: يناقش البرلمان مقترح ضريبة ويعدله ويصوت عليه بدل أن تطبقه جهة إدارية دون سند قانوني."},{"slug":"how-state-works","index":5,"old_lessons":[{"title":"الفكرة الأساسية","body":"السلطة التنفيذية تطبق القوانين وتدير الخدمات والسياسات العامة ضمن الصلاحيات والقيود التي يحددها النظام. لفهم هذا الدرس حدّد ما الذي يصفه المصطلح، والجهة أو العلاقة التي يتناولها، ثم فرّق بين الوصف النظري والممارسة الفعلية.","example":"تنفيذ","note":"استوعب العلاقة الأساسية قبل الاستنتاج منها."},{"title":"حالة تطبيقية محلولة","body":"تضع وزارة خطة تشغيل مستشفيات بناءً على موازنة وقانون قائمين ثم تتابع تنفيذها. جرّب تحليل الموقف بهذا الترتيب: حدد السند القانوني ← خطط للخدمة ← راقب التنفيذ. لا تنتقل إلى التقييم قبل توضيح المعطيات والجهات المعنية.","example":"حدد السند القانوني ← خطط للخدمة ← راقب التنفيذ","note":"هذه حالة افتراضية للتعلم وليست وصفًا لبلد أو مؤسسة بعينها."},{"title":"القيود والأخطاء الشائعة","body":"القرار الإداري ليس تشريعًا عامًا بلا حدود؛ يمكن أن يخضع للطعن والرقابة. عندما تصل إلى نتيجة، اذكر افتراضاتك وتأكد أن المعلومات كافية؛ فالموضوع قد يختلف باختلاف القواعد والظروف والبيانات.","example":"تحقق من الحدود قبل تعميم النتيجة","note":"التقييم يعتمد على استدلالك وفهمك وليس على رأيك السياسي."}],"old_intro":"السلطة التنفيذية تطبق القوانين وتدير الخدمات والسياسات العامة ضمن الصلاحيات والقيود التي يحددها النظام. تضع وزارة خطة تشغيل مستشفيات بناءً على موازنة وقانون قائمين ثم تتابع تنفيذها.","lessons":[{"title":"فهم المفهوم من البداية","body":"السلطة التنفيذية تطبق القوانين وتدير الخدمات والسياسات العامة ضمن الصلاحيات والقيود التي يحددها النظام.\n\nبعد صدور القانون تحتاج الدولة إلى موظفين وميزانيات ومشتريات وإدارة. التنفيذ يجيب عن سؤال «كيف نطبق القاعدة؟» لا «من يضعها؟».","example":"تنفيذ","note":"لا تحفظ المصطلح وحده: حاول أن تشرح فكرته بلغة بسيطة وبمثال قريب منك."},{"title":"مثال محلول: ماذا حدث؟","body":"تضع وزارة خطة تشغيل مستشفيات بناءً على موازنة وقانون قائمين ثم تتابع تنفيذها.\n\nوالآن تخيّل الموقف التالي: صدر قانون وموازنة لبناء عيادة عامة.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.","example":"صدر قانون وموازنة لبناء عيادة عامة.","note":"اقرأ السيناريو، وحدد المعطيات التي تعرفها قبل أي استنتاج."},{"title":"خطوات حل موقف مشابه","body":"أمامك موقف عملي في «السلطة التنفيذية». صدر قانون وموازنة لبناء عيادة عامة.\n\nالجهة التنفيذية تتولى التعاقد والإنفاق والإدارة بحسب القانون، مع خضوعها للرقابة.\n\nحتى تصل إلى تفسير سليم، مرّ على الإجراءات التالية بالترتيب. اشرح لنفسك لماذا تحتاج كل خطوة قبل الانتقال للأخرى.","example":"حدد السند القانوني ← خطط للخدمة ← راقب التنفيذ","note":"لا تتخطى خطوة لم تفهمها. قارن الإجابة بوقائع السيناريو."},{"title":"الحدود والأخطاء الشائعة","body":"القرار الإداري ليس تشريعًا عامًا بلا حدود؛ يمكن أن يخضع للطعن والرقابة.\n\nسؤال للمراجعة: أي جهة تبدأ التنفيذ اليومي للمشروع؟\n\nإذا لم تتوافر معلومات كافية للإجابة، فهذه علامة أنك تحتاج إلى بيانات أو قانون أو فترة مقارنة أو افتراضات أوضح. فهم ما لا تعرفه جزء أساسي من التحليل.","example":"أي جهة تبدأ التنفيذ اليومي للمشروع؟","note":"راجع خطأ شائعًا في هذا الموضوع ثم عد إلى المثال لتتأكد من فهمك."}],"intro":"في هذه المحطة سنفهم «السلطة التنفيذية» من البداية، من دون افتراض معرفة سابقة.\n\nالسلطة التنفيذية تطبق القوانين وتدير الخدمات والسياسات العامة ضمن الصلاحيات والقيود التي يحددها النظام.\n\nثم سنرى كيف تظهر الفكرة عمليًا، وما الذي قد نسيء فهمه: تضع وزارة خطة تشغيل مستشفيات بناءً على موازنة وقانون قائمين ثم تتابع تنفيذها."},{"slug":"how-state-works","index":6,"old_lessons":[{"title":"الفكرة الأساسية","body":"السلطة القضائية تفصل في المنازعات وتطبق القانون على الوقائع، وقد تراجع مشروعية أعمال السلطات بحسب النظام. لفهم هذا الدرس حدّد ما الذي يصفه المصطلح، والجهة أو العلاقة التي يتناولها، ثم فرّق بين الوصف النظري والممارسة الفعلية.","example":"قضاء","note":"استوعب العلاقة الأساسية قبل الاستنتاج منها."},{"title":"حالة تطبيقية محلولة","body":"عندما يطعن مواطن في قرار إداري تنظر المحكمة في الوقائع والقواعد والإجراءات ذات الصلة. جرّب تحليل الموقف بهذا الترتيب: استمع للوقائع ← طبق القانون ← بين أسباب الحكم. لا تنتقل إلى التقييم قبل توضيح المعطيات والجهات المعنية.","example":"استمع للوقائع ← طبق القانون ← بين أسباب الحكم","note":"هذه حالة افتراضية للتعلم وليست وصفًا لبلد أو مؤسسة بعينها."},{"title":"القيود والأخطاء الشائعة","body":"لا يمكن افتراض استقلال القضاء من اسمه فقط؛ يجب النظر إلى ضمانات التعيين والإجراءات والتدخلات. عندما تصل إلى نتيجة، اذكر افتراضاتك وتأكد أن المعلومات كافية؛ فالموضوع قد يختلف باختلاف القواعد والظروف والبيانات.","example":"تحقق من الحدود قبل تعميم النتيجة","note":"التقييم يعتمد على استدلالك وفهمك وليس على رأيك السياسي."}],"old_intro":"السلطة القضائية تفصل في المنازعات وتطبق القانون على الوقائع، وقد تراجع مشروعية أعمال السلطات بحسب النظام. عندما يطعن مواطن في قرار إداري تنظر المحكمة في الوقائع والقواعد والإجراءات ذات الصلة.","lessons":[{"title":"فهم المفهوم من البداية","body":"السلطة القضائية تفصل في المنازعات وتطبق القانون على الوقائع، وقد تراجع مشروعية أعمال السلطات بحسب النظام.\n\nالقاضي لا يصمم الخدمة العامة بديلًا عن الوزارة؛ يفصل في النزاع عندما يُعرض عليه وفق الاختصاص. لذلك يهتم بالأدلة والإجراءات والنصوص.","example":"قضاء","note":"لا تحفظ المصطلح وحده: حاول أن تشرح فكرته بلغة بسيطة وبمثال قريب منك."},{"title":"مثال محلول: ماذا حدث؟","body":"عندما يطعن مواطن في قرار إداري تنظر المحكمة في الوقائع والقواعد والإجراءات ذات الصلة.\n\nوالآن تخيّل الموقف التالي: رُفض ترخيص وفق قرار إداري، وصاحب الطلب يقول إن الإجراءات خالفت القانون.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.","example":"رُفض ترخيص وفق قرار إداري، وصاحب الطلب يقول إن الإجراءات خالفت القانون.","note":"اقرأ السيناريو، وحدد المعطيات التي تعرفها قبل أي استنتاج."},{"title":"خطوات حل موقف مشابه","body":"أمامك موقف عملي في «السلطة القضائية». رُفض ترخيص وفق قرار إداري، وصاحب الطلب يقول إن الإجراءات خالفت القانون.\n\nقد يتيح القانون تظلمًا إداريًا أو قضاءً مختصًا؛ المهم وجود مسار قانوني للفحص.\n\nحتى تصل إلى تفسير سليم، مرّ على الإجراءات التالية بالترتيب. اشرح لنفسك لماذا تحتاج كل خطوة قبل الانتقال للأخرى.","example":"استمع للوقائع ← طبق القانون ← بين أسباب الحكم","note":"لا تتخطى خطوة لم تفهمها. قارن الإجابة بوقائع السيناريو."},{"title":"الحدود والأخطاء الشائعة","body":"لا يمكن افتراض استقلال القضاء من اسمه فقط؛ يجب النظر إلى ضمانات التعيين والإجراءات والتدخلات.\n\nسؤال للمراجعة: أي طريق يفحص صحة تطبيق القواعد؟\n\nإذا لم تتوافر معلومات كافية للإجابة، فهذه علامة أنك تحتاج إلى بيانات أو قانون أو فترة مقارنة أو افتراضات أوضح. فهم ما لا تعرفه جزء أساسي من التحليل.","example":"أي طريق يفحص صحة تطبيق القواعد؟","note":"راجع خطأ شائعًا في هذا الموضوع ثم عد إلى المثال لتتأكد من فهمك."}],"intro":"في هذه المحطة سنفهم «السلطة القضائية» من البداية، من دون افتراض معرفة سابقة.\n\nالسلطة القضائية تفصل في المنازعات وتطبق القانون على الوقائع، وقد تراجع مشروعية أعمال السلطات بحسب النظام.\n\nثم سنرى كيف تظهر الفكرة عمليًا، وما الذي قد نسيء فهمه: عندما يطعن مواطن في قرار إداري تنظر المحكمة في الوقائع والقواعد والإجراءات ذات الصلة."},{"slug":"how-state-works","index":7,"old_lessons":[{"title":"الفكرة الأساسية","body":"سيادة القانون تعني خضوع ممارسة السلطة لقواعد معلنة وإجراءات يمكن الطعن فيها، مع حماية حقوق الأفراد وفق النظام. لفهم هذا الدرس حدّد ما الذي يصفه المصطلح، والجهة أو العلاقة التي يتناولها، ثم فرّق بين الوصف النظري والممارسة الفعلية.","example":"سيادة القانون","note":"استوعب العلاقة الأساسية قبل الاستنتاج منها."},{"title":"حالة تطبيقية محلولة","body":"عندما ترفض إدارة طلبًا عليها أن تلتزم بالإجراءات وتتيح طريق تظلم أو مراجعة حيث ينص القانون. جرّب تحليل الموقف بهذا الترتيب: حدد القاعدة ← افحص تطبيقها ← راجع وسيلة الطعن. لا تنتقل إلى التقييم قبل توضيح المعطيات والجهات المعنية.","example":"حدد القاعدة ← افحص تطبيقها ← راجع وسيلة الطعن","note":"هذه حالة افتراضية للتعلم وليست وصفًا لبلد أو مؤسسة بعينها."},{"title":"القيود والأخطاء الشائعة","body":"وجود قوانين كثيرة لا يثبت وحده المساواة في تطبيقها أو إمكان الوصول إلى العدالة. عندما تصل إلى نتيجة، اذكر افتراضاتك وتأكد أن المعلومات كافية؛ فالموضوع قد يختلف باختلاف القواعد والظروف والبيانات.","example":"تحقق من الحدود قبل تعميم النتيجة","note":"التقييم يعتمد على استدلالك وفهمك وليس على رأيك السياسي."}],"old_intro":"سيادة القانون تعني خضوع ممارسة السلطة لقواعد معلنة وإجراءات يمكن الطعن فيها، مع حماية حقوق الأفراد وفق النظام. عندما ترفض إدارة طلبًا عليها أن تلتزم بالإجراءات وتتيح طريق تظلم أو مراجعة حيث ينص القانون.","lessons":[{"title":"فهم المفهوم من البداية","body":"سيادة القانون تعني خضوع ممارسة السلطة لقواعد معلنة وإجراءات يمكن الطعن فيها، مع حماية حقوق الأفراد وفق النظام.\n\nالقاعدة المعلنة تحمي من القرارات المفاجئة إذا أمكن الاحتجاج بها ومراجعة تطبيقها. الفارق بين القانون والقرار الفردي مهم عند تقديم شكوى.","example":"سيادة القانون","note":"لا تحفظ المصطلح وحده: حاول أن تشرح فكرته بلغة بسيطة وبمثال قريب منك."},{"title":"مثال محلول: ماذا حدث؟","body":"عندما ترفض إدارة طلبًا عليها أن تلتزم بالإجراءات وتتيح طريق تظلم أو مراجعة حيث ينص القانون.\n\nوالآن تخيّل الموقف التالي: تلقّى شخص قرار رفض من إدارة محلية.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.","example":"تلقّى شخص قرار رفض من إدارة محلية.","note":"اقرأ السيناريو، وحدد المعطيات التي تعرفها قبل أي استنتاج."},{"title":"خطوات حل موقف مشابه","body":"أمامك موقف عملي في «سيادة القانون». تلقّى شخص قرار رفض من إدارة محلية.\n\nسيادة القانون تتصل بوضوح القواعد وإمكان الاحتجاج بها ومراجعة تطبيقها.\n\nحتى تصل إلى تفسير سليم، مرّ على الإجراءات التالية بالترتيب. اشرح لنفسك لماذا تحتاج كل خطوة قبل الانتقال للأخرى.","example":"حدد القاعدة ← افحص تطبيقها ← راجع وسيلة الطعن","note":"لا تتخطى خطوة لم تفهمها. قارن الإجابة بوقائع السيناريو."},{"title":"الحدود والأخطاء الشائعة","body":"وجود قوانين كثيرة لا يثبت وحده المساواة في تطبيقها أو إمكان الوصول إلى العدالة.\n\nسؤال للمراجعة: قارن ما الذي تتيحه كل آلية للمواطن.\n\nإذا لم تتوافر معلومات كافية للإجابة، فهذه علامة أنك تحتاج إلى بيانات أو قانون أو فترة مقارنة أو افتراضات أوضح. فهم ما لا تعرفه جزء أساسي من التحليل.","example":"قارن ما الذي تتيحه كل آلية للمواطن.","note":"راجع خطأ شائعًا في هذا الموضوع ثم عد إلى المثال لتتأكد من فهمك."}],"intro":"في هذه المحطة سنفهم «سيادة القانون» من البداية، من دون افتراض معرفة سابقة.\n\nسيادة القانون تعني خضوع ممارسة السلطة لقواعد معلنة وإجراءات يمكن الطعن فيها، مع حماية حقوق الأفراد وفق النظام.\n\nثم سنرى كيف تظهر الفكرة عمليًا، وما الذي قد نسيء فهمه: عندما ترفض إدارة طلبًا عليها أن تلتزم بالإجراءات وتتيح طريق تظلم أو مراجعة حيث ينص القانون."},{"slug":"how-state-works","index":8,"old_lessons":[{"title":"الفكرة الأساسية","body":"توزع الإدارة المحلية بعض الخدمات والقرارات بين المستوى الوطني والسلطات المحلية وفق قانون يحدد الموارد والصلاحيات. لفهم هذا الدرس حدّد ما الذي يصفه المصطلح، والجهة أو العلاقة التي يتناولها، ثم فرّق بين الوصف النظري والممارسة الفعلية.","example":"إدارة محلية","note":"استوعب العلاقة الأساسية قبل الاستنتاج منها."},{"title":"حالة تطبيقية محلولة","body":"قد يتولى مجلس محلي إدارة النظافة بينما تحدد الدولة المعايير العامة أو التمويل المشترك. جرّب تحليل الموقف بهذا الترتيب: حدد الخدمة ← حدد مستوى المسؤولية ← راجع التمويل والرقابة. لا تنتقل إلى التقييم قبل توضيح المعطيات والجهات المعنية.","example":"حدد الخدمة ← حدد مستوى المسؤولية ← راجع التمويل والرقابة","note":"هذه حالة افتراضية للتعلم وليست وصفًا لبلد أو مؤسسة بعينها."},{"title":"القيود والأخطاء الشائعة","body":"اللامركزية الإدارية ليست بالضرورة فيدرالية سياسية؛ توزيع الاختصاصات يختلف بينهما. عندما تصل إلى نتيجة، اذكر افتراضاتك وتأكد أن المعلومات كافية؛ فالموضوع قد يختلف باختلاف القواعد والظروف والبيانات.","example":"تحقق من الحدود قبل تعميم النتيجة","note":"التقييم يعتمد على استدلالك وفهمك وليس على رأيك السياسي."}],"old_intro":"توزع الإدارة المحلية بعض الخدمات والقرارات بين المستوى الوطني والسلطات المحلية وفق قانون يحدد الموارد والصلاحيات. قد يتولى مجلس محلي إدارة النظافة بينما تحدد الدولة المعايير العامة أو التمويل المشترك.","lessons":[{"title":"فهم المفهوم من البداية","body":"توزع الإدارة المحلية بعض الخدمات والقرارات بين المستوى الوطني والسلطات المحلية وفق قانون يحدد الموارد والصلاحيات.\n\nقد تكون خدمة النظافة محلية بينما تكون معايير الصحة وطنية. اعرف الجهة المخولة بدل افتراض أن كل مشكلة تقع على الحكومة المركزية وحدها.","example":"إدارة محلية","note":"لا تحفظ المصطلح وحده: حاول أن تشرح فكرته بلغة بسيطة وبمثال قريب منك."},{"title":"مثال محلول: ماذا حدث؟","body":"قد يتولى مجلس محلي إدارة النظافة بينما تحدد الدولة المعايير العامة أو التمويل المشترك.\n\nوالآن تخيّل الموقف التالي: مدينة تشكو من جمع النفايات. يتولى المجلس المحلي الخدمة بتمويل منصوص عليه.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.","example":"مدينة تشكو من جمع النفايات. يتولى المجلس المحلي الخدمة بتمويل منصوص عليه.","note":"اقرأ السيناريو، وحدد المعطيات التي تعرفها قبل أي استنتاج."},{"title":"خطوات حل موقف مشابه","body":"أمامك موقف عملي في «الإدارة المحلية». مدينة تشكو من جمع النفايات. يتولى المجلس المحلي الخدمة بتمويل منصوص عليه.\n\nتعرف الجهة المسؤولة من القانون المحلي لا من حجم الخدمة أو شهرة المؤسسة.\n\nحتى تصل إلى تفسير سليم، مرّ على الإجراءات التالية بالترتيب. اشرح لنفسك لماذا تحتاج كل خطوة قبل الانتقال للأخرى.","example":"حدد الخدمة ← حدد مستوى المسؤولية ← راجع التمويل والرقابة","note":"لا تتخطى خطوة لم تفهمها. قارن الإجابة بوقائع السيناريو."},{"title":"الحدود والأخطاء الشائعة","body":"اللامركزية الإدارية ليست بالضرورة فيدرالية سياسية؛ توزيع الاختصاصات يختلف بينهما.\n\nسؤال للمراجعة: إلى أي مستوى تتجه الشكوى عن الجدول اليومي أولًا؟\n\nإذا لم تتوافر معلومات كافية للإجابة، فهذه علامة أنك تحتاج إلى بيانات أو قانون أو فترة مقارنة أو افتراضات أوضح. فهم ما لا تعرفه جزء أساسي من التحليل.","example":"إلى أي مستوى تتجه الشكوى عن الجدول اليومي أولًا؟","note":"راجع خطأ شائعًا في هذا الموضوع ثم عد إلى المثال لتتأكد من فهمك."}],"intro":"في هذه المحطة سنفهم «الإدارة المحلية» من البداية، من دون افتراض معرفة سابقة.\n\nتوزع الإدارة المحلية بعض الخدمات والقرارات بين المستوى الوطني والسلطات المحلية وفق قانون يحدد الموارد والصلاحيات.\n\nثم سنرى كيف تظهر الفكرة عمليًا، وما الذي قد نسيء فهمه: قد يتولى مجلس محلي إدارة النظافة بينما تحدد الدولة المعايير العامة أو التمويل المشترك."},{"slug":"how-state-works","index":9,"old_lessons":[{"title":"الفكرة الأساسية","body":"المؤسسات العامة تنفذ وظائف محددة بميزانيات وموظفين وإجراءات، وتحتاج إلى بيانات لتقييم مستوى الخدمة. لفهم هذا الدرس حدّد ما الذي يصفه المصطلح، والجهة أو العلاقة التي يتناولها، ثم فرّق بين الوصف النظري والممارسة الفعلية.","example":"خدمة عامة","note":"استوعب العلاقة الأساسية قبل الاستنتاج منها."},{"title":"حالة تطبيقية محلولة","body":"ترصد إدارة مدرسة عدد الطلاب والمعلمين والاحتياجات قبل توزيع الحصص والمعدات. جرّب تحليل الموقف بهذا الترتيب: حدد المستفيدين ← احسب الموارد ← قارن الخدمة الفعلية بالهدف. لا تنتقل إلى التقييم قبل توضيح المعطيات والجهات المعنية.","example":"حدد المستفيدين ← احسب الموارد ← قارن الخدمة الفعلية بالهدف","note":"هذه حالة افتراضية للتعلم وليست وصفًا لبلد أو مؤسسة بعينها."},{"title":"القيود والأخطاء الشائعة","body":"زيادة الإنفاق وحدها لا تثبت تحسن الخدمة؛ يجب قياس المخرجات والجودة وتفاوت الوصول. عندما تصل إلى نتيجة، اذكر افتراضاتك وتأكد أن المعلومات كافية؛ فالموضوع قد يختلف باختلاف القواعد والظروف والبيانات.","example":"تحقق من الحدود قبل تعميم النتيجة","note":"التقييم يعتمد على استدلالك وفهمك وليس على رأيك السياسي."}],"old_intro":"المؤسسات العامة تنفذ وظائف محددة بميزانيات وموظفين وإجراءات، وتحتاج إلى بيانات لتقييم مستوى الخدمة. ترصد إدارة مدرسة عدد الطلاب والمعلمين والاحتياجات قبل توزيع الحصص والمعدات.","lessons":[{"title":"فهم المفهوم من البداية","body":"المؤسسات العامة تنفذ وظائف محددة بميزانيات وموظفين وإجراءات، وتحتاج إلى بيانات لتقييم مستوى الخدمة.\n\nلتحسين خدمة مدرسة نحتاج أكثر من شراء الأجهزة: عدد المستفيدين، تدريب العاملين، الصيانة وطريقة التوزيع. القياس يبدأ بتحديد ما نريد تحسينه.","example":"خدمة عامة","note":"لا تحفظ المصطلح وحده: حاول أن تشرح فكرته بلغة بسيطة وبمثال قريب منك."},{"title":"مثال محلول: ماذا حدث؟","body":"ترصد إدارة مدرسة عدد الطلاب والمعلمين والاحتياجات قبل توزيع الحصص والمعدات.\n\nوالآن تخيّل الموقف التالي: إدارة تعليم لديها 20 فصلًا وتريد توزيع الحواسيب.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.","example":"إدارة تعليم لديها 20 فصلًا وتريد توزيع الحواسيب.","note":"اقرأ السيناريو، وحدد المعطيات التي تعرفها قبل أي استنتاج."},{"title":"خطوات حل موقف مشابه","body":"أمامك موقف عملي في «المؤسسات والخدمة العامة». إدارة تعليم لديها 20 فصلًا وتريد توزيع الحواسيب.\n\nالمتوسط لا يكشف وحده إن كانت الأجهزة تعمل أو توزعت بالتساوي؛ هذه أسئلة متابعة مهمة.\n\nحتى تصل إلى تفسير سليم، مرّ على الإجراءات التالية بالترتيب. اشرح لنفسك لماذا تحتاج كل خطوة قبل الانتقال للأخرى.","example":"حدد المستفيدين ← احسب الموارد ← قارن الخدمة الفعلية بالهدف","note":"لا تتخطى خطوة لم تفهمها. قارن الإجابة بوقائع السيناريو."},{"title":"الحدود والأخطاء الشائعة","body":"زيادة الإنفاق وحدها لا تثبت تحسن الخدمة؛ يجب قياس المخرجات والجودة وتفاوت الوصول.\n\nسؤال للمراجعة: غيّر عدد الأجهزة وعدد الفصول، وشاهد متوسط الأجهزة لكل فصل.\n\nإذا لم تتوافر معلومات كافية للإجابة، فهذه علامة أنك تحتاج إلى بيانات أو قانون أو فترة مقارنة أو افتراضات أوضح. فهم ما لا تعرفه جزء أساسي من التحليل.","example":"غيّر عدد الأجهزة وعدد الفصول، وشاهد متوسط الأجهزة لكل فصل.","note":"راجع خطأ شائعًا في هذا الموضوع ثم عد إلى المثال لتتأكد من فهمك."}],"intro":"في هذه المحطة سنفهم «المؤسسات والخدمة العامة» من البداية، من دون افتراض معرفة سابقة.\n\nالمؤسسات العامة تنفذ وظائف محددة بميزانيات وموظفين وإجراءات، وتحتاج إلى بيانات لتقييم مستوى الخدمة.\n\nثم سنرى كيف تظهر الفكرة عمليًا، وما الذي قد نسيء فهمه: ترصد إدارة مدرسة عدد الطلاب والمعلمين والاحتياجات قبل توزيع الحصص والمعدات."},{"slug":"how-state-works","index":10,"old_lessons":[{"title":"الفكرة الأساسية","body":"المساءلة تعني مطالبة جهة بتفسير قراراتها ومراجعتها وفق اختصاص واضح، والشفافية تتيح المعلومات ذات الصلة. لفهم هذا الدرس حدّد ما الذي يصفه المصطلح، والجهة أو العلاقة التي يتناولها، ثم فرّق بين الوصف النظري والممارسة الفعلية.","example":"مساءلة","note":"استوعب العلاقة الأساسية قبل الاستنتاج منها."},{"title":"حالة تطبيقية محلولة","body":"ينشر جهاز عام تقرير إنفاق ثم تراجع جهة رقابية مدى الالتزام بالإجراءات والنتائج. جرّب تحليل الموقف بهذا الترتيب: اطلب البيانات ← حدد المسؤولية ← راجع القرار والنتائج. لا تنتقل إلى التقييم قبل توضيح المعطيات والجهات المعنية.","example":"اطلب البيانات ← حدد المسؤولية ← راجع القرار والنتائج","note":"هذه حالة افتراضية للتعلم وليست وصفًا لبلد أو مؤسسة بعينها."},{"title":"القيود والأخطاء الشائعة","body":"نشر الأرقام دون تفسير أو إمكانية للمراجعة لا يكفي وحده لتحقيق مساءلة فعالة. عندما تصل إلى نتيجة، اذكر افتراضاتك وتأكد أن المعلومات كافية؛ فالموضوع قد يختلف باختلاف القواعد والظروف والبيانات.","example":"تحقق من الحدود قبل تعميم النتيجة","note":"التقييم يعتمد على استدلالك وفهمك وليس على رأيك السياسي."}],"old_intro":"المساءلة تعني مطالبة جهة بتفسير قراراتها ومراجعتها وفق اختصاص واضح، والشفافية تتيح المعلومات ذات الصلة. ينشر جهاز عام تقرير إنفاق ثم تراجع جهة رقابية مدى الالتزام بالإجراءات والنتائج.","lessons":[{"title":"فهم المفهوم من البداية","body":"المساءلة تعني مطالبة جهة بتفسير قراراتها ومراجعتها وفق اختصاص واضح، والشفافية تتيح المعلومات ذات الصلة.\n\nشفافية الأرقام تعني قدرة الناس على رؤية معلومات مفهومة. المساءلة تبدأ عندما يمكن سؤال جهة معينة عما فعلت وتفسير القرارات ومراجعتها.","example":"مساءلة","note":"لا تحفظ المصطلح وحده: حاول أن تشرح فكرته بلغة بسيطة وبمثال قريب منك."},{"title":"مثال محلول: ماذا حدث؟","body":"ينشر جهاز عام تقرير إنفاق ثم تراجع جهة رقابية مدى الالتزام بالإجراءات والنتائج.\n\nوالآن تخيّل الموقف التالي: نشر جهاز حكومي تقريرًا يقول إنه أنفق موازنة مشروع عام.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.","example":"نشر جهاز حكومي تقريرًا يقول إنه أنفق موازنة مشروع عام.","note":"اقرأ السيناريو، وحدد المعطيات التي تعرفها قبل أي استنتاج."},{"title":"خطوات حل موقف مشابه","body":"أمامك موقف عملي في «المساءلة والشفافية». نشر جهاز حكومي تقريرًا يقول إنه أنفق موازنة مشروع عام.\n\nالشفافية توفر معلومات، أما المساءلة فتتطلب سؤال المسؤولين ومراجعة الأداء.\n\nحتى تصل إلى تفسير سليم، مرّ على الإجراءات التالية بالترتيب. اشرح لنفسك لماذا تحتاج كل خطوة قبل الانتقال للأخرى.","example":"اطلب البيانات ← حدد المسؤولية ← راجع القرار والنتائج","note":"لا تتخطى خطوة لم تفهمها. قارن الإجابة بوقائع السيناريو."},{"title":"الحدود والأخطاء الشائعة","body":"نشر الأرقام دون تفسير أو إمكانية للمراجعة لا يكفي وحده لتحقيق مساءلة فعالة.\n\nسؤال للمراجعة: ما أول إجراء واضح يمكن فعله وفق ما تعلمته؟\n\nإذا لم تتوافر معلومات كافية للإجابة، فهذه علامة أنك تحتاج إلى بيانات أو قانون أو فترة مقارنة أو افتراضات أوضح. فهم ما لا تعرفه جزء أساسي من التحليل.","example":"ما أول إجراء واضح يمكن فعله وفق ما تعلمته؟","note":"راجع خطأ شائعًا في هذا الموضوع ثم عد إلى المثال لتتأكد من فهمك."}],"intro":"في هذه المحطة سنفهم «المساءلة والشفافية» من البداية، من دون افتراض معرفة سابقة.\n\nالمساءلة تعني مطالبة جهة بتفسير قراراتها ومراجعتها وفق اختصاص واضح، والشفافية تتيح المعلومات ذات الصلة.\n\nثم سنرى كيف تظهر الفكرة عمليًا، وما الذي قد نسيء فهمه: ينشر جهاز عام تقرير إنفاق ثم تراجع جهة رقابية مدى الالتزام بالإجراءات والنتائج."},{"slug":"how-state-works","index":11,"old_lessons":[{"title":"الفكرة الأساسية","body":"يتطلب تصميم مؤسسات دولة افتراضية تحديد الوظائف والسلطات والموارد والرقابة وطرق حل النزاعات بينها. لفهم هذا الدرس حدّد ما الذي يصفه المصطلح، والجهة أو العلاقة التي يتناولها، ثم فرّق بين الوصف النظري والممارسة الفعلية.","example":"مؤسسة","note":"استوعب العلاقة الأساسية قبل الاستنتاج منها."},{"title":"حالة تطبيقية محلولة","body":"عند إنشاء هيئة خدمات جديدة تحتاج إلى اختصاص قانوني وميزانية وآلية لتقديم الشكاوى. جرّب تحليل الموقف بهذا الترتيب: حدد المهمة ← وزع الصلاحيات ← صمم الرقابة والمراجعة. لا تنتقل إلى التقييم قبل توضيح المعطيات والجهات المعنية.","example":"حدد المهمة ← وزع الصلاحيات ← صمم الرقابة والمراجعة","note":"هذه حالة افتراضية للتعلم وليست وصفًا لبلد أو مؤسسة بعينها."},{"title":"القيود والأخطاء الشائعة","body":"لا يوجد توزيع رقمي واحد للصلاحيات يضمن جودة الحكم؛ السياق والحقوق والتطبيق أمور حاسمة. عندما تصل إلى نتيجة، اذكر افتراضاتك وتأكد أن المعلومات كافية؛ فالموضوع قد يختلف باختلاف القواعد والظروف والبيانات.","example":"تحقق من الحدود قبل تعميم النتيجة","note":"التقييم يعتمد على استدلالك وفهمك وليس على رأيك السياسي."}],"old_intro":"يتطلب تصميم مؤسسات دولة افتراضية تحديد الوظائف والسلطات والموارد والرقابة وطرق حل النزاعات بينها. عند إنشاء هيئة خدمات جديدة تحتاج إلى اختصاص قانوني وميزانية وآلية لتقديم الشكاوى.","lessons":[{"title":"فهم المفهوم من البداية","body":"يتطلب تصميم مؤسسات دولة افتراضية تحديد الوظائف والسلطات والموارد والرقابة وطرق حل النزاعات بينها.\n\nالهيئة الجديدة لا تعمل بمجرد كتابة اسمها. اسأل عن الأساس القانوني والموارد وطريق الاعتراض ومن يراجع الأخطاء قبل اعتماد تصميمها.","example":"مؤسسة","note":"لا تحفظ المصطلح وحده: حاول أن تشرح فكرته بلغة بسيطة وبمثال قريب منك."},{"title":"مثال محلول: ماذا حدث؟","body":"عند إنشاء هيئة خدمات جديدة تحتاج إلى اختصاص قانوني وميزانية وآلية لتقديم الشكاوى.\n\nوالآن تخيّل الموقف التالي: ستؤسس هيئة جديدة لخدمة المواطنين. راجع ثلاث قرارات تأسيسية.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.","example":"ستؤسس هيئة جديدة لخدمة المواطنين. راجع ثلاث قرارات تأسيسية.","note":"اقرأ السيناريو، وحدد المعطيات التي تعرفها قبل أي استنتاج."},{"title":"خطوات حل موقف مشابه","body":"أمامك موقف عملي في «مشروع بناء مؤسسات الدولة». ستؤسس هيئة جديدة لخدمة المواطنين. راجع ثلاث قرارات تأسيسية.\n\nالمؤسسات تحتاج قواعد ووظائف وموارد ومراجعة، لا مجرد اسم أو مبنى.\n\nحتى تصل إلى تفسير سليم، مرّ على الإجراءات التالية بالترتيب. اشرح لنفسك لماذا تحتاج كل خطوة قبل الانتقال للأخرى.","example":"حدد المهمة ← وزع الصلاحيات ← صمم الرقابة والمراجعة","note":"لا تتخطى خطوة لم تفهمها. قارن الإجابة بوقائع السيناريو."},{"title":"الحدود والأخطاء الشائعة","body":"لا يوجد توزيع رقمي واحد للصلاحيات يضمن جودة الحكم؛ السياق والحقوق والتطبيق أمور حاسمة.\n\nسؤال للمراجعة: اختر أحد القرارات لتعرف فائدته ومخاطره.\n\nإذا لم تتوافر معلومات كافية للإجابة، فهذه علامة أنك تحتاج إلى بيانات أو قانون أو فترة مقارنة أو افتراضات أوضح. فهم ما لا تعرفه جزء أساسي من التحليل.","example":"اختر أحد القرارات لتعرف فائدته ومخاطره.","note":"راجع خطأ شائعًا في هذا الموضوع ثم عد إلى المثال لتتأكد من فهمك."}],"intro":"في هذه المحطة سنفهم «مشروع بناء مؤسسات الدولة» من البداية، من دون افتراض معرفة سابقة.\n\nيتطلب تصميم مؤسسات دولة افتراضية تحديد الوظائف والسلطات والموارد والرقابة وطرق حل النزاعات بينها.\n\nثم سنرى كيف تظهر الفكرة عمليًا، وما الذي قد نسيء فهمه: عند إنشاء هيئة خدمات جديدة تحتاج إلى اختصاص قانوني وميزانية وآلية لتقديم الشكاوى."},{"slug":"political-systems","index":0,"old_lessons":[{"title":"الفكرة الأساسية","body":"الجمهورية والملكية تصفان أسلوب شغل منصب رأس الدولة؛ وقد تختلف صلاحياته الفعلية كثيرًا داخل كل فئة. لفهم هذا الدرس حدّد ما الذي يصفه المصطلح، والجهة أو العلاقة التي يتناولها، ثم فرّق بين الوصف النظري والممارسة الفعلية.","example":"رأس الدولة","note":"استوعب العلاقة الأساسية قبل الاستنتاج منها."},{"title":"حالة تطبيقية محلولة","body":"قد يكون الملك صاحب دور رمزي في نظام برلماني، بينما يتمتع رئيس جمهورية بصلاحيات تنفيذية أوسع في نظام آخر. جرّب تحليل الموقف بهذا الترتيب: حدد طريقة تولي المنصب ← افحص الصلاحيات ← قارن مؤسسات الرقابة. لا تنتقل إلى التقييم قبل توضيح المعطيات والجهات المعنية.","example":"حدد طريقة تولي المنصب ← افحص الصلاحيات ← قارن مؤسسات الرقابة","note":"هذه حالة افتراضية للتعلم وليست وصفًا لبلد أو مؤسسة بعينها."},{"title":"القيود والأخطاء الشائعة","body":"لا تستنتج درجة المشاركة الشعبية أو الحقوق من لقب رئيس الدولة وحده. عندما تصل إلى نتيجة، اذكر افتراضاتك وتأكد أن المعلومات كافية؛ فالموضوع قد يختلف باختلاف القواعد والظروف والبيانات.","example":"تحقق من الحدود قبل تعميم النتيجة","note":"التقييم يعتمد على استدلالك وفهمك وليس على رأيك السياسي."}],"old_intro":"الجمهورية والملكية تصفان أسلوب شغل منصب رأس الدولة؛ وقد تختلف صلاحياته الفعلية كثيرًا داخل كل فئة. قد يكون الملك صاحب دور رمزي في نظام برلماني، بينما يتمتع رئيس جمهورية بصلاحيات تنفيذية أوسع في نظام آخر.","lessons":[{"title":"فهم المفهوم من البداية","body":"الجمهورية والملكية تصفان أسلوب شغل منصب رأس الدولة؛ وقد تختلف صلاحياته الفعلية كثيرًا داخل كل فئة.\n\nاسم رأس الدولة يخبرك عن طريقة شغل المنصب غالبًا، لكنه لا يخبرك وحده من يدير الحكومة أو كيف يراقب البرلمان السلطة التنفيذية.","example":"رأس الدولة","note":"لا تحفظ المصطلح وحده: حاول أن تشرح فكرته بلغة بسيطة وبمثال قريب منك."},{"title":"مثال محلول: ماذا حدث؟","body":"قد يكون الملك صاحب دور رمزي في نظام برلماني، بينما يتمتع رئيس جمهورية بصلاحيات تنفيذية أوسع في نظام آخر.\n\nوالآن تخيّل الموقف التالي: بلد ملكي يملك فيه البرلمان سلطة اختيار الحكومة، وبلد جمهوري يدير فيه الرئيس الحكومة.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.","example":"بلد ملكي يملك فيه البرلمان سلطة اختيار الحكومة، وبلد جمهوري يدير فيه الرئيس الحكومة.","note":"اقرأ السيناريو، وحدد المعطيات التي تعرفها قبل أي استنتاج."},{"title":"خطوات حل موقف مشابه","body":"أمامك موقف عملي في «الجمهورية والملكية». بلد ملكي يملك فيه البرلمان سلطة اختيار الحكومة، وبلد جمهوري يدير فيه الرئيس الحكومة.\n\nالملكية والجمهورية تصفان رأس الدولة، أما صلاحيات الحكومة فتحتاج قراءة مؤسسات الحكم.\n\nحتى تصل إلى تفسير سليم، مرّ على الإجراءات التالية بالترتيب. اشرح لنفسك لماذا تحتاج كل خطوة قبل الانتقال للأخرى.","example":"حدد طريقة تولي المنصب ← افحص الصلاحيات ← قارن مؤسسات الرقابة","note":"لا تتخطى خطوة لم تفهمها. قارن الإجابة بوقائع السيناريو."},{"title":"الحدود والأخطاء الشائعة","body":"لا تستنتج درجة المشاركة الشعبية أو الحقوق من لقب رئيس الدولة وحده.\n\nسؤال للمراجعة: ما الذي يجب فحصه قبل مقارنة الصلاحيات؟\n\nإذا لم تتوافر معلومات كافية للإجابة، فهذه علامة أنك تحتاج إلى بيانات أو قانون أو فترة مقارنة أو افتراضات أوضح. فهم ما لا تعرفه جزء أساسي من التحليل.","example":"ما الذي يجب فحصه قبل مقارنة الصلاحيات؟","note":"راجع خطأ شائعًا في هذا الموضوع ثم عد إلى المثال لتتأكد من فهمك."}],"intro":"في هذه المحطة سنفهم «الجمهورية والملكية» من البداية، من دون افتراض معرفة سابقة.\n\nالجمهورية والملكية تصفان أسلوب شغل منصب رأس الدولة؛ وقد تختلف صلاحياته الفعلية كثيرًا داخل كل فئة.\n\nثم سنرى كيف تظهر الفكرة عمليًا، وما الذي قد نسيء فهمه: قد يكون الملك صاحب دور رمزي في نظام برلماني، بينما يتمتع رئيس جمهورية بصلاحيات تنفيذية أوسع في نظام آخر."},{"slug":"political-systems","index":1,"old_lessons":[{"title":"الفكرة الأساسية","body":"في النظام الرئاسي يُنتخب الرئيس عادةً لولاية محددة ويقود السلطة التنفيذية بصورة منفصلة عن ثقة البرلمان. لفهم هذا الدرس حدّد ما الذي يصفه المصطلح، والجهة أو العلاقة التي يتناولها، ثم فرّق بين الوصف النظري والممارسة الفعلية.","example":"رئاسي","note":"استوعب العلاقة الأساسية قبل الاستنتاج منها."},{"title":"حالة تطبيقية محلولة","body":"قد ينتخب المواطنون رئيسًا وبرلمانًا على نحو منفصل فيختلف الانتماء الحزبي بين المؤسستين. جرّب تحليل الموقف بهذا الترتيب: حدد مصدر الشرعية ← افحص العلاقة بالبرلمان ← راجع آلية العزل والمساءلة. لا تنتقل إلى التقييم قبل توضيح المعطيات والجهات المعنية.","example":"حدد مصدر الشرعية ← افحص العلاقة بالبرلمان ← راجع آلية العزل والمساءلة","note":"هذه حالة افتراضية للتعلم وليست وصفًا لبلد أو مؤسسة بعينها."},{"title":"القيود والأخطاء الشائعة","body":"التفاصيل الدستورية تختلف؛ ولا يعني الفصل المؤسسي غياب تعاون أو رقابة بين السلطات. عندما تصل إلى نتيجة، اذكر افتراضاتك وتأكد أن المعلومات كافية؛ فالموضوع قد يختلف باختلاف القواعد والظروف والبيانات.","example":"تحقق من الحدود قبل تعميم النتيجة","note":"التقييم يعتمد على استدلالك وفهمك وليس على رأيك السياسي."}],"old_intro":"في النظام الرئاسي يُنتخب الرئيس عادةً لولاية محددة ويقود السلطة التنفيذية بصورة منفصلة عن ثقة البرلمان. قد ينتخب المواطنون رئيسًا وبرلمانًا على نحو منفصل فيختلف الانتماء الحزبي بين المؤسستين.","lessons":[{"title":"فهم المفهوم من البداية","body":"في النظام الرئاسي يُنتخب الرئيس عادةً لولاية محددة ويقود السلطة التنفيذية بصورة منفصلة عن ثقة البرلمان.\n\nفي النظام الرئاسي عادة توجد شرعية انتخابية منفصلة للرئيس والبرلمان. لهذا قد يحتاج الطرفان إلى التفاوض لإقرار القوانين والموازنة.","example":"رئاسي","note":"لا تحفظ المصطلح وحده: حاول أن تشرح فكرته بلغة بسيطة وبمثال قريب منك."},{"title":"مثال محلول: ماذا حدث؟","body":"قد ينتخب المواطنون رئيسًا وبرلمانًا على نحو منفصل فيختلف الانتماء الحزبي بين المؤسستين.\n\nوالآن تخيّل الموقف التالي: في نظام افتراضي ينتخب المواطنون الرئيس والبرلمان كلًا على حدة.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.","example":"في نظام افتراضي ينتخب المواطنون الرئيس والبرلمان كلًا على حدة.","note":"اقرأ السيناريو، وحدد المعطيات التي تعرفها قبل أي استنتاج."},{"title":"خطوات حل موقف مشابه","body":"أمامك موقف عملي في «النظام الرئاسي». في نظام افتراضي ينتخب المواطنون الرئيس والبرلمان كلًا على حدة.\n\nالانتخاب المنفصل من خصائص الأنظمة الرئاسية عادة، مع فروق تفصيلية بين الدول.\n\nحتى تصل إلى تفسير سليم، مرّ على الإجراءات التالية بالترتيب. اشرح لنفسك لماذا تحتاج كل خطوة قبل الانتقال للأخرى.","example":"حدد مصدر الشرعية ← افحص العلاقة بالبرلمان ← راجع آلية العزل والمساءلة","note":"لا تتخطى خطوة لم تفهمها. قارن الإجابة بوقائع السيناريو."},{"title":"الحدود والأخطاء الشائعة","body":"التفاصيل الدستورية تختلف؛ ولا يعني الفصل المؤسسي غياب تعاون أو رقابة بين السلطات.\n\nسؤال للمراجعة: أي وصف ينسجم مع الصورة العامة للنظام الرئاسي؟\n\nإذا لم تتوافر معلومات كافية للإجابة، فهذه علامة أنك تحتاج إلى بيانات أو قانون أو فترة مقارنة أو افتراضات أوضح. فهم ما لا تعرفه جزء أساسي من التحليل.","example":"أي وصف ينسجم مع الصورة العامة للنظام الرئاسي؟","note":"راجع خطأ شائعًا في هذا الموضوع ثم عد إلى المثال لتتأكد من فهمك."}],"intro":"في هذه المحطة سنفهم «النظام الرئاسي» من البداية، من دون افتراض معرفة سابقة.\n\nفي النظام الرئاسي يُنتخب الرئيس عادةً لولاية محددة ويقود السلطة التنفيذية بصورة منفصلة عن ثقة البرلمان.\n\nثم سنرى كيف تظهر الفكرة عمليًا، وما الذي قد نسيء فهمه: قد ينتخب المواطنون رئيسًا وبرلمانًا على نحو منفصل فيختلف الانتماء الحزبي بين المؤسستين."},{"slug":"political-systems","index":2,"old_lessons":[{"title":"الفكرة الأساسية","body":"في النظام البرلماني تنشأ الحكومة عادةً من أغلبية البرلمان أو ائتلاف يحظى بثقته ويمكن مساءلته سياسيًا. لفهم هذا الدرس حدّد ما الذي يصفه المصطلح، والجهة أو العلاقة التي يتناولها، ثم فرّق بين الوصف النظري والممارسة الفعلية.","example":"برلماني","note":"استوعب العلاقة الأساسية قبل الاستنتاج منها."},{"title":"حالة تطبيقية محلولة","body":"تفاوض أحزاب على اتفاق ائتلاف لتشكيل وزارة تحصل على ثقة المجلس المنتخب. جرّب تحليل الموقف بهذا الترتيب: حدد نتائج المقاعد ← ابحث عن دعم الأغلبية ← افحص الثقة والمساءلة. لا تنتقل إلى التقييم قبل توضيح المعطيات والجهات المعنية.","example":"حدد نتائج المقاعد ← ابحث عن دعم الأغلبية ← افحص الثقة والمساءلة","note":"هذه حالة افتراضية للتعلم وليست وصفًا لبلد أو مؤسسة بعينها."},{"title":"القيود والأخطاء الشائعة","body":"يمكن أن يختلف دور رئيس الدولة عن رئيس الحكومة؛ ولا تكون كل الأنظمة البرلمانية متطابقة. عندما تصل إلى نتيجة، اذكر افتراضاتك وتأكد أن المعلومات كافية؛ فالموضوع قد يختلف باختلاف القواعد والظروف والبيانات.","example":"تحقق من الحدود قبل تعميم النتيجة","note":"التقييم يعتمد على استدلالك وفهمك وليس على رأيك السياسي."}],"old_intro":"في النظام البرلماني تنشأ الحكومة عادةً من أغلبية البرلمان أو ائتلاف يحظى بثقته ويمكن مساءلته سياسيًا. تفاوض أحزاب على اتفاق ائتلاف لتشكيل وزارة تحصل على ثقة المجلس المنتخب.","lessons":[{"title":"فهم المفهوم من البداية","body":"في النظام البرلماني تنشأ الحكومة عادةً من أغلبية البرلمان أو ائتلاف يحظى بثقته ويمكن مساءلته سياسيًا.\n\nفي النظام البرلماني لا يكفي إعلان حزب فوزه؛ يجب معرفة عدد المقاعد ومن يستطيع دعم الحكومة. إذا فقدت الثقة فقد تتغير الحكومة وفق الإجراءات.","example":"برلماني","note":"لا تحفظ المصطلح وحده: حاول أن تشرح فكرته بلغة بسيطة وبمثال قريب منك."},{"title":"مثال محلول: ماذا حدث؟","body":"تفاوض أحزاب على اتفاق ائتلاف لتشكيل وزارة تحصل على ثقة المجلس المنتخب.\n\nوالآن تخيّل الموقف التالي: أفرزت الانتخابات مجلسًا لا يملك فيه أي حزب أكثر من نصف المقاعد.\n\nهذان موقفان مختلفان يوضحان كيف يظهر المفهوم نفسه في الحياة العملية. لاحظ الأشخاص والجهات أو الأرقام التي تغيّرت بين الحالتين.","example":"أفرزت الانتخابات مجلسًا لا يملك فيه أي حزب أكثر من نصف المقاعد.","note":"اقرأ السيناريو، وحدد المعطيات التي تعرفها قبل أي استنتاج."},{"title":"خطوات حل موقف مشابه","body":"أمامك موقف عملي في «النظام البرلماني». أفرزت الانتخابات مجلسًا لا يملك فيه أي حزب أكثر من نصف المقاعد.\n\nالائتلاف وسيلة للحصول على دعم برلماني ولا يعني ذوبان برامج الأحزاب.\n\nحتى تصل إلى تفسير سليم، مرّ على الإجراءات التالية بالترتيب. اشرح لنفسك لماذا تحتاج كل خطوة قبل الانتقال للأخرى.","example":"حدد نتائج المقاعد ← ابحث عن دعم الأغلبية ← افحص الثقة والمساءلة","note":"لا تتخطى خطوة لم تفهمها. قارن الإجابة بوقائع السيناريو."},{"title":"الحدود والأخطاء الشائعة","body":"يمكن أن يختلف دور رئيس الدولة عن رئيس الحكومة؛ ولا تكون كل الأنظمة البرلمانية متطابقة.\n\nسؤال للمراجعة: ما أول إجراء واضح يمكن فعله وفق ما تعلمته؟\n\nإذا لم تتوافر معلومات كافية للإجابة، فهذه علامة أنك تحتاج إلى بيانات أو قانون أو فترة مقارنة أو افتراضات أوضح. فهم ما لا تعرفه جزء أساسي من التحليل.","example":"ما أول إجراء واضح يمكن فعله وفق ما تعلمته؟","note":"راجع خطأ شائعًا في هذا الموضوع ثم عد إلى المثال لتتأكد من فهمك."}],"intro":"في هذه المحطة سنفهم «النظام البرلماني» من البداية، من دون افتراض معرفة سابقة.\n\nفي النظام البرلماني تنشأ الحكومة عادةً من أغلبية البرلمان أو ائتلاف يحظى بثقته ويمكن مساءلته سياسيًا.\n\nثم سنرى كيف تظهر الفكرة عمليًا، وما الذي قد نسيء فهمه: تفاوض أحزاب على اتفاق ائتلاف لتشكيل وزارة تحصل على ثقة المجلس المنتخب."},{"slug":"political-systems","index":3,"old_lessons":[{"title":"الفكرة الأساسية","body":"يجمع النظام شبه الرئاسي عادةً رئيسًا منتخبًا مباشرة وحكومة يقودها رئيس وزراء مسؤول أمام البرلمان. لفهم هذا الدرس حدّد ما الذي يصفه المصطلح، والجهة أو العلاقة التي يتناولها، ثم فرّق بين الوصف النظري والممارسة الفعلية.","example":"شبه رئاسي","note":"استوعب العلاقة الأساسية قبل الاستنتاج منها."},{"title":"حالة تطبيقية محلولة","body":"قد تتقاسم مؤسسة الرئاسة ورئاسة الحكومة صلاحيات تختلف بحسب الدستور والائتلاف البرلماني. جرّب تحليل الموقف بهذا الترتيب: حدد دور الرئيس ← حدد دور الحكومة ← افحص المسؤولية أمام البرلمان. لا تنتقل إلى التقييم قبل توضيح المعطيات والجهات المعنية.","example":"حدد دور الرئيس ← حدد دور الحكومة ← افحص المسؤولية أمام البرلمان","note":"هذه حالة افتراضية للتعلم وليست وصفًا لبلد أو مؤسسة بعينها."},{"title":"القيود والأخطاء الشائعة","body":"لا تتحدد الصلاحيات من الاسم فقط؛ ينبغي قراءة الدستور وتطبيقه في الظروف المختلفة. عندما تصل إلى نتيجة، اذكر افتراضاتك وتأكد أن المعلومات كافية؛ فالموضوع قد يختلف باختلاف القواعد والظروف والبيانات.","example":"تحقق من الحدود قبل تعميم النتيجة","note":"التقييم يعتمد على استدلالك 